17	    int32_t tile_size;
18	    int32_t block_rows;
19	    int32_t dtype;
20	};
21	
22	at::Tensor swiglu(const at::Tensor &x, int64_t dim)
23	{
24	    // Normalize dim
25	    int64_t normalizedDim = dim;
26	    if (dim < 0) {
27	        normalizedDim = x.dim() + dim;
28	    }
29	    TORCH_CHECK(normalizedDim == x.dim() - 1,
30	                "swiglu: chunk dim must be the last dim; reshape in wrapper");
31	    TORCH_CHECK(x.is_contiguous(), "swiglu: input must be contiguous");
32	
33	    int64_t D = x.sizes()[x.dim() - 1];
34	    TORCH_CHECK(D % 2 == 0, "swiglu: chunk dim must be even, got ", D);
35	
36	    int64_t totalRows = 1;
37	    for (int64_t i = 0; i < x.dim() - 1; ++i) {
38	        totalRows *= x.sizes()[i];
39	    }
40	    int64_t halfD = D / 2;
41	
42	    // Create output tensor with correct shape
43	    std::vector<int64_t> outShape(x.sizes().begin(), x.sizes().end());
44	    outShape.back() = halfD;
45	    at::Tensor y = at::empty(outShape, x.options());
46	
47	    // dtype mapping
48	    int32_t dtypeVal = 0;
49	    if (x.scalar_type() == at::kHalf) {
50	        dtypeVal = 1;
51	    } else if (x.scalar_type() == at::kBFloat16) {
52	        dtypeVal = 2;
53	    } else {
54	        TORCH_CHECK(x.scalar_type() == at::kFloat,
55	                    "swiglu: only float32/float16/bfloat16 supported");
56	    }
57	
58	    // Bfloat16: convert to float32 for kernel, cast back
59	    at::Tensor xKernel = x;
60	    at::Tensor yKernel = y;
61	    if (x.scalar_type() == at::kBFloat16) {
62	        xKernel = x.to(at::kFloat);
63	        yKernel = at::empty(outShape, xKernel.options());
64	    }
65	
66	    // Tiling data
67	    at::Tensor t = at::empty({static_cast<int64_t>(sizeof(SwiGLUTiling))},
68	                             at::device(at::kCPU).dtype(at::kByte));
69	    auto *tilingPtr = reinterpret_cast<SwiGLUTiling *>(t.data_ptr());
70	    tilingPtr->totalRows = static_cast<int32_t>(totalRows);
71	    tilingPtr->D = static_cast<int32_t>(D);
72	    tilingPtr->halfD = static_cast<int32_t>(halfD);
73	    tilingPtr->tile_size = 2048;
74	    tilingPtr->block_rows = 8;
75	    tilingPtr->dtype = dtypeVal;
76	
77	    auto tilingNpu = t.to(at::kPrivateUse1);
78	
79	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
80	    uint32_t usedCoreNum = ascendcPlatform->GetCoreNumAic();
81	    uint32_t blockDim = usedCoreNum;
82	
83	    if (x.scalar_type() == at::kFloat) {
84	        EXEC_KERNEL_CMD(swiglu_fp32, blockDim, xKernel, yKernel, tilingNpu);
85	    } else {
86	        EXEC_KERNEL_CMD(swiglu_fp16, blockDim, xKernel, yKernel, tilingNpu);
87	    }
88	
89	    if (x.scalar_type() == at::kBFloat16) {
90	        return yKernel.to(at::kBFloat16);
91	    }
92	    return y;
93	}
94	
95	} // namespace ascend_kernel
