6	/**
7	 * @file swiglu.cpp
8	 * @brief AscendC kernel for SwiGLU: y = silu(a) * b
9	 *
10	 * Input is pre-shaped to [total_rows, D] with chunk dim as last dim.
11	 * Kernel processes [total_rows, D] -> [total_rows, D/2].
12	 * Each block handles block_rows rows. Within each row, tiles along D/2.
13	 *
14	 * Uses DataCopy with 32-byte aligned copy sizes.
15	 * Uses Silu API for direct silu computation.
16	 * depth=1 TQue with return-value AllocTensor/DeQue.
17	 * PipeBarrier provides pipeline synchronization.
18	 */
19	
20	#include "kernel_operator.h"
21	using namespace AscendC;
22	
23	struct SwiGLUTiling {
24	    int32_t totalRows;
25	    int32_t D;
26	    int32_t halfD;
27	    int32_t tile_size;
28	    int32_t block_rows;
29	    int32_t dtype;
30	};
31	
32	__aicore__ inline void CopyTiling(SwiGLUTiling *dst, GM_ADDR src)
33	{
34	    auto *d = reinterpret_cast<int32_t *>(dst);
35	    auto *s = reinterpret_cast<__gm__ int32_t *>(src);
36	    for (size_t i = 0; i < sizeof(SwiGLUTiling) / sizeof(int32_t); ++i) {
37	        d[i] = s[i];
38	    }
39	}
40	
41	template <typename T>
42	class SwiGLUKernel {
43	public:
44	    __aicore__ inline SwiGLUKernel() {}
45	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM);
46	    __aicore__ inline void Process();
47	
48	private:
49	    GlobalTensor<T> xGM_;
50	    GlobalTensor<T> yGM_;
51	    SwiGLUTiling tiling_;
52	    TPipe pipe_;
53	    TQue<TPosition::VECIN, 1> inQueueA_;
54	    TQue<TPosition::VECIN, 1> inQueueB_;
55	    TQue<TPosition::VECOUT, 1> outQueueS_;
56	    TQue<TPosition::VECOUT, 1> outQueueY_;
57	    LocalTensor<T> aLocal_;
58	    LocalTensor<T> bLocal_;
59	    LocalTensor<T> sLocal_;
60	    LocalTensor<T> yLocal_;
61	    uint32_t tileSize_;
62	};
63	
64	template <typename T>
65	__aicore__ inline void SwiGLUKernel<T>::Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM)
66	{
67	    CopyTiling(&tiling_, tGM);
68	
69	    int64_t inputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.D;
70	    int64_t outputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.halfD;
71	    xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), inputSize);
72	    yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), outputSize);
73	
74	    tileSize_ = static_cast<uint32_t>(tiling_.tile_size);
75	
76	    // depth=1 TQue with return-value AllocTensor and DeQue
77	    uint8_t bufNum = 1;
78	    uint32_t bufSize = static_cast<uint32_t>(tileSize_) * static_cast<uint32_t>(sizeof(T));
79	    pipe_.InitBuffer(inQueueA_, bufNum, bufSize);
80	    pipe_.InitBuffer(inQueueB_, bufNum, bufSize);
81	    pipe_.InitBuffer(outQueueS_, bufNum, bufSize);
82	    pipe_.InitBuffer(outQueueY_, bufNum, bufSize);
83	
84	    aLocal_ = inQueueA_.AllocTensor<T>();
85	    bLocal_ = inQueueB_.AllocTensor<T>();
86	    sLocal_ = outQueueS_.AllocTensor<T>();
87	    yLocal_ = outQueueY_.AllocTensor<T>();
88	}
89	
90	template <typename T>
91	__aicore__ inline void SwiGLUKernel<T>::Process()
92	{
93	    int32_t blockIdx = GetBlockIdx();
94	    int32_t rowBase = blockIdx * tiling_.block_rows;
95	    int32_t totalRows = tiling_.totalRows;
96	    int32_t D = tiling_.D;
97	    int32_t halfD = tiling_.halfD;
98	    uint32_t tileSize = tileSize_;
99	    int32_t blockRows = tiling_.block_rows;
100	    int32_t blockNum = (totalRows + blockRows - 1) / blockRows;
101	    int32_t coreNum = GetBlockNum();
102	
103	    // Persistent-kernel: each core processes blocks strided by coreNum
104	    for (int32_t b = blockIdx; b < blockNum; b += coreNum) {
105	        int32_t rowBase = b * blockRows;
106	        int32_t rowsInBlock = blockRows;
107	        if (rowBase + blockRows > totalRows) {
108	            rowsInBlock = totalRows - rowBase;
109	        }
110	
111	        for (int32_t r = 0; r < rowsInBlock; ++r) {
112	            int32_t rowIdx = rowBase + r;
113	
114	            int64_t rowOffset = static_cast<int64_t>(rowIdx) * D;
115	            int64_t aOffset = rowOffset;
116	            int64_t bOffset = rowOffset + halfD;
117	            int64_t yOffset = static_cast<int64_t>(rowIdx) * halfD;
118	
119	            int32_t numTiles = (halfD + static_cast<int32_t>(tileSize) - 1) / static_cast<int32_t>(tileSize);
120	            for (int32_t t = 0; t < numTiles; ++t) {
121	                int32_t start = t * tileSize;
122	                int32_t curSize = (tileSize < static_cast<uint32_t>(halfD - start))
123	                                      ? static_cast<int32_t>(tileSize)
124	                                      : (halfD - start);
125	                uint32_t uCurSize = static_cast<uint32_t>(curSize);
126	
127	                // Round up to 32-byte aligned size for DataCopy
128	                uint32_t bytes = uCurSize * sizeof(T);
129	                uint32_t alignedBytes = (bytes + 31) / 32 * 32;
130	                uint32_t alignedSize = alignedBytes / sizeof(T);
131	
132	                // --- CopyIn: load a segment with aligned copy ---
133	                DataCopy(aLocal_, xGM_[aOffset + start], alignedSize);
134	                inQueueA_.EnQue(aLocal_);
135	                LocalTensor<T> aDeq = inQueueA_.DeQue<T>();
136	
137	                // --- CopyIn: load b segment ---
138	                DataCopy(bLocal_, xGM_[bOffset + start], alignedSize);
139	                inQueueB_.EnQue(bLocal_);
140	                LocalTensor<T> bDeq = inQueueB_.DeQue<T>();
141	
142	                // --- Compute: silu(a) -> s ---
143	                Silu(sLocal_, aDeq, uCurSize);
144	                PipeBarrier<PIPE_V>();
145	
146	                // --- Compute: result = silu(a) * b -> y ---
147	                Mul(yLocal_, sLocal_, bDeq, uCurSize);
148	                PipeBarrier<PIPE_V>();
149	
150	                // --- CopyOut: enqueue, dequeue, write exact count ---
151	                // Use DataCopy for aligned portion + scalar for remainder
152	                outQueueY_.EnQue(yLocal_);
153	                LocalTensor<T> yDeq = outQueueY_.DeQue<T>();
154	                uint32_t alignedPartSize = (uCurSize / (32 / sizeof(T))) * (32 / sizeof(T));
155	                if (alignedPartSize > 0) {
156	                    DataCopy(yGM_[yOffset + start], yDeq, alignedPartSize);
157	                }
158	                PipeBarrier<PIPE_ALL>();
159	                for (uint32_t i = alignedPartSize; i < uCurSize; ++i) {
160	                    yGM_[yOffset + start + i] = yDeq[i];
161	                }
162	
163	                // --- Ensure CopyOut completes ---
164	                PipeBarrier<PIPE_ALL>();
165	            }
166	        }
167	    }
168	
169	    // Free all tensors
170	    outQueueS_.FreeTensor(sLocal_);
171	    outQueueY_.FreeTensor(yLocal_);
172	    inQueueA_.FreeTensor(aLocal_);
173	    inQueueB_.FreeTensor(bLocal_);
174	}
175	
176	extern "C" __global__ __aicore__ void swiglu_fp32(GM_ADDR x, GM_ADDR y, GM_ADDR tiling)
177	{
178	    SwiGLUKernel<float> kernel;
179	    kernel.Init(x, y, tiling);
180	    kernel.Process();
181	}
182	
183	extern "C" __global__ __aicore__ void swiglu_fp16(GM_ADDR x, GM_ADDR y, GM_ADDR tiling)
184	{
185	    SwiGLUKernel<half> kernel;
186	    kernel.Init(x, y, tiling);
187	    kernel.Process();
188	}
